import * as fs from 'fs';

export async function handleRead(path: string): Promise<string> {
  try {
    if (!fs.existsSync(path)) {
      console.error(`Error: file not found at ${path}`);
      throw new Error('File not found');
    }
    return fs.readFileSync(path, 'utf-8');
  } catch (err) {
    if (err instanceof Error && err.message === 'File not found') throw err;
    console.error(`Error reading ${path}: ${err instanceof Error ? err.message : err}`);
    throw new Error(`Failed to read ${path}`);
  }
}

export async function handleWrite(path: string, content: string): Promise<void> {
  try {
    const dir = path.substring(0, path.lastIndexOf('/'));
    if (dir && !fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path, content, 'utf-8');
  } catch (err) {
    console.error(`Error writing ${path}: ${err instanceof Error ? err.message : err}`);
    throw new Error(`Failed to write ${path}`);
  }
}

